import{_ as e,o as l,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-09-12 :: Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-09-12 :: Ceph Performance Meeting","date":"2019-09-12T00:00:00.000Z","updated":"2019-09-21T00:00:00.000Z","tags":["[Ceph]","[分布式存储]","[性能优化]","[存储集群]","[性能测试]"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-09-12_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-09-12_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),n={name:"posts/2019/2019-09-12_-_-_Ceph_Performance_Meeting.md"};function s(o,i,a,g,_,p){return l(),t("div",null,[...i[0]||(i[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年9月12日 <strong>会议地点</strong>： 线上会议 <strong>参会人员</strong>： Mark, Garrett, Eric, Casey, Sage, Neha, Igor, OSHA, Ping, Adam, Josh, 等 <strong>会议主题</strong>： Ceph分布式存储项目进展讨论</p><p><strong>主要讨论议题</strong>：</p><ul><li><strong>SATA SSD利用率</strong>： 讨论了SATA SSD的利用率，指出其接近最大吞吐量，具体取决于设备性能和IO负载类型。</li><li><strong>Luminous代码改进</strong>： 讨论了Luminous代码的改进，包括性能提升和功能增强。</li><li><strong>CLS代码中的过滤功能</strong>： 讨论了在OSD中的CLS代码中实现过滤功能的改进，包括对性能提升和减少网络使用量的影响。</li><li><strong>bucket reshaping性能</strong>： 讨论了bucket reshaping的性能，包括在resharding过程中允许客户端写入和优化锁定机制。</li><li><strong>4K金属块大小</strong>： 讨论了在OMAP中使用4K金属块大小对性能和空间利用率的影响。</li><li><strong>小对象在OMAP中的存储</strong>： 讨论了在OMAP中使用小对象（小于4K）存储的改进，包括对性能和空间利用率的影响。</li></ul><p><strong>决定事项</strong>：</p><ul><li>推进Luminous代码的改进，并迁移到Nautilus代码库进行对比测试。</li><li>评估CLS代码中过滤功能的性能提升和网络使用量减少。</li><li>研究bucket resharding的性能和优化锁定机制。</li><li>在OMAP中使用4K金属块大小进行测试，并评估其对性能和空间利用率的影响。</li><li>对小对象在OMAP中的存储进行改进，并评估其对性能和空间利用率的影响。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Mark将继续推进Luminous代码的改进。</li><li>Eric将评估CLS代码中过滤功能的性能提升和网络使用量减少。</li><li>Casey将研究bucket resharding的性能和优化锁定机制。</li><li>Josh将测试4K金属块大小在OMAP中的性能和空间利用率。</li><li>OSHA和Ping将评估小对象在OMAP中的存储改进。</li></ul><p><strong>其他事项</strong>：</p><ul><li>会议中提到了许多其他PR和改进，包括自动更新、测试、性能优化等。</li><li>会议讨论了如何进行基准测试和验证回归。</li><li>会议讨论了如何优化小对象存储。</li></ul><p><strong>关键词</strong>：</p><ul><li>Ceph</li><li>Luminous</li><li>Nautilus</li><li>SATA SSD</li><li>CLS</li><li>bucket resharding</li><li>4K金属块大小</li><li>OMAP</li><li>小对象</li><li>性能优化</li><li>测试</li><li>回归</li></ul>',12)])])}const d=e(n,[["render",s]]);export{c as __pageData,d as default};
